  "draft.missing": ["सूचना का मसौदा।", "సమాచార చిత్తు.", "The intimation draft."],
  "draft.no_draft": ["इस जाँच में मसौदा नहीं बना।", "ఈ పరిశీలనలో చిత్తు రాలేదు.", "No draft was produced in this run."],
  "draft.no_evidence": ["मसौदा जाँच के बाद बनता है।", "పరిశీలన తర్వాత చిత్తు వస్తుంది.", "The draft is written after the inquiry."],
  "file.title": ["मैंने सूचना दे दी", "నేను సమాచారం ఇచ్చాను", "I have reported it"],
  "file.not_yet": ["अभी दर्ज नहीं। संदर्भ संख्या मिलने पर ही इसे दर्ज माना जाएगा।", "ఇంకా నమోదు కాలేదు. రిఫరెన్స్ సంఖ్య వచ్చాకే నమోదు.", "Not recorded yet. It counts as filed only once you have a reference number."],
