  "file.ref_required": ["संदर्भ संख्या के बिना इसे दर्ज नहीं माना जा सकता।", "రిఫరెన్స్ సంఖ్య లేకుండా నమోదు కాదు.", "This cannot be recorded without a reference number."],
  "file.save": ["दर्ज करें", "నమోదు చేయండి", "Record it"],
  "file.stamp": ["दर्ज", "నమోదు", "Filed"],
  "file.self_reported": ["यह आपकी दी हुई जानकारी है। हम बीमा कंपनी के पास कुछ नहीं भेजते।", "ఇది మీరు ఇచ్చిన సమాచారం. మేము బీమా కంపెనీకి ఏమీ పంపం.", "This is what you told us. We send nothing to an insurer."],
  "file.add_another": ["एक और संदर्भ जोड़ें", "ఇంకో రిఫరెన్స్ చేర్చండి", "Add another reference"],
