const IDX: Record<Lang, 0 | 1 | 2> = { hi: 0, te: 1, en: 2 };

export function keyLabel(k: string, lang: Lang): string {
  const row = LABELS[k] ?? LABELS[k.split(".").pop() ?? k];
  return row ? row[IDX[lang]] : k.replace(/_/g, " ");
}

