const RUBRIC_PATTERNS: [RegExp, string, string][] = [
  [/^plot NDVI change ([-+\d.]+) \(threshold ([-\d.]+)\)$/, "खेत का NDVI बदलाव $1 (सीमा $2)", "పొలం NDVI మార్పు $1 (పరిమితి $2)"],
  [/^plot NDVI change ([-+\d.]+)$/, "खेत का NDVI बदलाव $1", "పొలం NDVI మార్పు $1"],
  [/^optical placebo p = ([\d.]+) \(threshold ([\d.]+)\)$/, "तुलना का p-मान $1 (सीमा $2)", "పోలిక p-విలువ $1 (పరిమితి $2)"],
  [/^optical placebo p = ([\d.]+)$/, "तुलना का p-मान $1", "పోలిక p-విలువ $1"],
  [/^corroborated by (.+)$/, "$1 से पुष्टि", "$1 తో నిర్ధారణ"],
];

export function translateRubric(s: string, lang: Lang): string {
  if (lang === "en") return s;
  const i = lang === "hi" ? 0 : 1;
  const exact = RUBRIC_EXACT[s];
  if (exact) return exact[i];
  for (const [re, hi, te] of RUBRIC_PATTERNS) {
    if (re.test(s)) return s.replace(re, i === 0 ? hi : te);
  }
  return s;
}

interface Ctx {
  lang: Lang;
  setLang: (l: Lang) => void;
  t: (key: Key, vars?: Record<string, string | number>) => string;
}
const I18nContext = createContext<Ctx | null>(null);

function initialLang(): Lang {
  const fromUrl = new URLSearchParams(location.search).get("lang");
  if (fromUrl === "hi" || fromUrl === "te" || fromUrl === "en") return fromUrl;
  try {
    const stored = localStorage.getItem("fs.lang");
    if (stored === "hi" || stored === "te" || stored === "en") return stored;
  } catch { /* private mode */ }
  return "hi";
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>(initialLang);
  const setLang = useCallback((l: Lang) => {
    setLangState(l);
    try { localStorage.setItem("fs.lang", l); } catch { /* private mode */ }
  }, []);
  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dataset.lang = lang;
    document.title = S["brand.name"][IDX[lang]];
  }, [lang]);
  const value = useMemo<Ctx>(() => ({
    lang,
    setLang,
    t: (key, vars) => {
      const row: Row | undefined = S[key];
      let out: string = row ? row[IDX[lang]] : key;
      if (vars) for (const [k, v] of Object.entries(vars)) out = out.replaceAll(`{${k}}`, String(v));
      return out;
    },
  }), [lang, setLang]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): Ctx {
  const c = useContext(I18nContext);
  if (!c) throw new Error("useI18n outside I18nProvider");
  return c;
}
